# -*- coding: utf-8 -*-
"""
Shot seeder for project «ТЫ — Маляр» (slug: painter).
Idempotent: ON CONFLICT (projectId, shotCode) DO NOTHING — safe to re-run / append.
promptFields = {positive, positivePrompt (mirror), narrationRu (VO), motionPrompt, motionNegative}.
env shots -> painter_environment, renderMode=static, isBroll=true, no participant.
char shots -> painter_character_ip, renderMode=animated, one participant (profile).
Run: PYTHONIOENCODING=utf-8 python seed_painter_shots.py
"""
import uuid, json, psycopg2

conn = psycopg2.connect(host="localhost", dbname="gen_studio", user="gen_studio", password="gen_studio")
conn.set_client_encoding("UTF8")
cur = conn.cursor()
cur.execute("SELECT id FROM projects WHERE slug='painter'")
pid = cur.fetchone()[0]

cur.execute("SELECT \"sceneKey\", id FROM scenes WHERE \"projectId\"=%s", (pid,))
SCENE = {k: v for k, v in cur.fetchall()}
cur.execute("""SELECT cp."profileCode", cp.id, cp."characterId"
               FROM character_profiles cp JOIN characters c ON cp."characterId"=c.id
               WHERE c."projectId"=%s""", (pid,))
PROF = {pc: (pidp, cid) for pc, pidp, cid in cur.fetchall()}
cur.execute("SELECT slug, id FROM locations WHERE \"projectId\"=%s", (pid,))
LOC = {s: i for s, i in cur.fetchall()}

ENV_MP = ("only ambient environmental motion, slow drifting dust and light, gently shifting light and shadow, "
          "faint wind in the scene, an empty scene with no people and no figures, the cell-shaded illustration "
          "softly coming to life, hand-drawn animation cadence")
ENV_MN = ("people, person, man, woman, human figure, figures, characters, crowd, silhouettes of people, "
          "anime character, anime girl, manga character, extra humans appearing, cars, vehicles, doors opening, "
          "photoreal, photograph, 3D render, plastic skin, deformed, flicker, warping")
CHAR_MP = ("subtle natural motion of only the figure already present in the frame, small breathing and quiet "
           "micro-movements continuing the moment, no new people entering, no extra figures appearing, the "
           "cell-shaded illustration in motion, hand-drawn animation cadence")
CHAR_MN = ("extra people, additional figures, duplicate person, twin, clone, background crowd, anime character, "
           "anime girl, manga character, extra limbs, deformed face, photoreal, photograph, 3D render, plastic skin, "
           "flicker, warping")

n_ins = 0
def add(code, sk, route, prof, loc, st, ang, mv, rmode, broll, iconic, vo, pos):
    global n_ins
    sid = str(uuid.uuid4())
    routekey = "painter_environment" if route == "env" else "painter_character_ip"
    refid = PROF[prof][0] if prof else None
    mp, mn = (ENV_MP, ENV_MN) if route == "env" else (CHAR_MP, CHAR_MN)
    pf = json.dumps({"positive": pos, "positivePrompt": pos, "narrationRu": vo,
                     "motionPrompt": mp, "motionNegative": mn}, ensure_ascii=False)
    cur.execute("""INSERT INTO shots
        (id,"projectId","sceneId","shotCode","promptFields","workflowRouteKey","referenceProfileId",
         "renderMode","narrationText","shotType","cameraAngle","cameraMove","isBroll","isIconic","locationId","updatedAt")
        VALUES (%s,%s,%s,%s,%s::jsonb,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now())
        ON CONFLICT ("projectId","shotCode") DO NOTHING RETURNING id""",
        (sid, pid, SCENE[sk], code, pf, routekey, refid, rmode, vo, st, ang, mv, broll, iconic,
         LOC.get(loc) if loc else None))
    row = cur.fetchone()
    if row:
        n_ins += 1
        if prof:
            profid, charid = PROF[prof]
            cur.execute("""INSERT INTO shot_participants (id,"shotId","characterId","profileId",label)
                           VALUES (%s,%s,%s,%s,%s)""", (str(uuid.uuid4()), sid, charid, profid, prof))

S = "act"  # noqa
